import type { PracticeExam } from './lccaExams';

export const lcpaaExamsPartA: PracticeExam[] = [
  {
    id: 'lcpaa-exam-1',
    number: 1,
    title: 'LCPAA Practice Exam 1',
    description: 'Foundational: core facts from Subchapters A-F, including agency organization, administrator duties, reporting and records, staff and caregiver qualifications, and training hours.',
    questions: [
      { id: 'p1q1', domain: 'Definitions (Subch. B)', question: 'Under the definitions in Chapter 749, a CPA administrator who must be a "full-time employee" works at least how many hours per week?', options: ['20 hours', '30 hours', '35 hours', '40 hours'], correct: 1, explanation: '§749.43(32) defines full-time as at least 30 hours per week. Under §749.631(a)(3) the child-placing agency administrator must be a full-time employee of the agency, and §749.151(1) requires you to have a designated full-time administrator while operating.' },
      { id: 'p1q2', domain: 'Agency Administration (Subch. C)', question: 'When your child-placing agency administrator changes, or the administrator position becomes vacant, written notice to your Licensing Representative is due:', options: ['As soon as possible, but no later than two days after the change', 'At least 15 days before the change', 'At least 30 days before the change', 'Within 10 business days after the change'], correct: 0, explanation: '§749.153(a)(3)(A) requires written notification as soon as possible, but no later than two days after you change your administrator or the position becomes vacant. The same two-day timeline applies when someone becomes, or stops being, a controlling person.' },
      { id: 'p1q3', domain: 'Agency Administration (Subch. C)', question: 'Which change requires written notification to your Licensing Representative at least 30 days BEFORE it occurs?', options: ['Changing the child-placing agency administrator', 'A new individual becoming a controlling person', 'Opening a branch office', 'Changing the plan that evaluates the effectiveness of your system for meeting the rules'], correct: 2, explanation: '§749.153(a)(1)(C) requires notice at least 30 days before you open a branch office (changing your legal structure, relocating, or changing hours of operation also require 30 days). Administrator and controlling-person changes are due within two days after the change, and changes to the §749.101(3) and (4) plans are due at least 15 days before (§749.153(a)(2)-(3)).' },
      { id: 'p1q4', domain: 'Agency Administration (Subch. C)', question: 'If your administrator position becomes vacant and you have no back-up administrator to carry out the administrator duties, how long do you have to obtain a licensed child-care administrator before Licensing can cite you for not having one?', options: ['15 days', '30 days', '45 days', '60 days'], correct: 3, explanation: '§749.154 gives you 60 days from the date the position becomes vacant to obtain a licensed child-care administrator when you have no back-up administrator. Notice of the vacancy to Licensing is still due within two days under §749.153(a)(3)(A).' },
      { id: 'p1q5', domain: 'Fiscal Requirements (Subch. C)', question: 'Unless you have an acceptable reason not to carry it, what amount of liability insurance coverage must a child-placing agency maintain?', options: ['$100,000 for each occurrence of negligence', '$300,000 for each occurrence of negligence', '$500,000 for each occurrence of negligence', '$1,000,000 for each occurrence of negligence'], correct: 1, explanation: '§749.155(1) requires $300,000 in liability coverage for each occurrence of negligence that covers injury to a child on your premises or in your care, and §749.155(2) requires you to give Licensing proof of coverage each year by the anniversary date of the issuance of your permit.' },
      { id: 'p1q6', domain: 'Fiscal Requirements (Subch. C)', question: 'A CPA that previously carried the required liability insurance stops carrying it. Within how long must it notify, in writing, the parent of each child in its care?', options: ['14 days after it stops carrying the insurance', '7 days after it stops carrying the insurance', '30 days after it stops carrying the insurance', '60 days after it stops carrying the insurance'], correct: 0, explanation: '§749.159(b) requires written notice to the parent of each child in your care within 14 days after you stop carrying the liability insurance. If you never carried the required insurance, §749.159(a) requires written notice before you admit the child.' },
      { id: 'p1q7', domain: 'Personnel Policies (Subch. C)', question: 'Your personnel policies must address how employees report suspected abuse, neglect, or exploitation. Which approach is consistent with §749.105(6)?', options: ['The employee reports to the administrator first, and the administrator decides whether the Hotline is called', 'The employee may delegate the report to a supervisor who agrees to call the Hotline', 'The employee reports directly to the Texas Abuse and Neglect Hotline and may not delegate the report or be required to seek approval first', 'The employee waits for child placement management staff to confirm the suspicion before reporting'], correct: 2, explanation: '§749.105(6) requires employees who suspect abuse, neglect, or exploitation to report directly to the Texas Abuse and Neglect Hotline. An employee may not delegate the responsibility to report, and you may not require an employee to seek approval to file a report or to notify you that a report was made (see also §749.607(2)).' },
      { id: 'p1q8', domain: 'Fiscal Requirements (Subch. C)', question: 'As an alternative to an annual review of financial records by an independent Certified Public Accountant, a CPA may make available proof of reserve funds equal to at least how much operating expense?', options: ['One month of operating expenses', 'Two months of operating expenses', 'Six months of operating expenses', 'Three months of operating expenses'], correct: 3, explanation: '§749.161(b)(2) requires you to make available either an annual review of your financial records by an independent CPA under Generally Accepted Accounting Principles, or proof of reserve funds equal to at least three months of operating expenses for your agency.' },
      { id: 'p1q9', domain: 'Branch Offices (Subch. C)', question: 'A child-placing agency must have a main or branch office in each department region where it verifies homes, OR within what distance of each verified foster home?', options: ['50 miles', '150 miles', '250 miles', '300 miles'], correct: 1, explanation: '§749.304 requires a main or branch office either in each region of the department where you verify homes, or within 150 miles of each verified foster home. The Technical Assistance explains that radial miles are used to calculate the distance.' },
      { id: 'p1q10', domain: 'Branch Offices (Subch. C)', question: 'Offices may share the same administrator and treatment director only if caseload limits are met. For a caseload of foster HOMES only, what is the maximum?', options: ['15 homes', '20 homes', '25 homes', '30 homes'], correct: 0, explanation: '§749.305(a)(2)(B) allows offices to share an administrator and treatment director when the child placement staff caseload of foster homes only does not exceed 15 homes. Other limits are 35 children (child-care services), 25 (treatment services), 30 (combination), or a combined 30 cases counting each child and each home as one case.' },
      { id: 'p1q11', domain: 'Administrator Qualifications (Subch. E)', question: 'A child-placing agency administrator may serve as administrator for two residential child-care operations only if, among other conditions, at least one child-placing agency is managing no more than how many foster homes?', options: ['10 foster homes', '15 foster homes', '25 foster homes', '50 foster homes'], correct: 2, explanation: '§749.633(4) requires that at least one child-placing agency is managing 25 or fewer foster homes. The administrator must also have both operations in good standing, the size and scope must be manageable by one person per the professional staffing plans, and the person must hold a valid Child-Care Administrator License if the second operation is a child-placing agency (§749.633(1)-(3)).' },
      { id: 'p1q12', domain: 'Treatment Director (Subch. E)', question: 'A child-placing agency must have a full-time treatment director if it provides treatment services to:', options: ['10 or more children at any one time, or more than 25% of the children in care', '20 or more children at any one time, or more than 40% of the children in care', '25 or more children at any one time, or more than 75% of the children in care', '30 or more children at any one time, or more than 50% of the children in care'], correct: 3, explanation: '§749.721 requires a treatment director if you provide treatment services to 30 or more children at any one time, or to more than 50% of the children in your care. The treatment director must be a full-time employee of your agency.' },
      { id: 'p1q13', domain: 'Serious Incidents (Subch. D)', question: 'A child dies while in the CPA\'s care. Law enforcement must be notified:', options: ['Within 30 minutes of the death', 'Immediately, but no later than 1 hour after the child\'s death', 'As soon as possible, but no later than 2 hours after the death', 'As soon as possible, but no later than 24 hours after the death'], correct: 1, explanation: 'Under §749.503(a)(1), the CPA reports to law enforcement immediately, but no later than 1 hour after the child\'s death. Child Care Regulation and the parents must be notified as soon as possible, but no later than 2 hours after the death. Reports go directly to the Texas Abuse and Neglect Hotline (§749.509(a)).' },
      { id: 'p1q14', domain: 'Serious Incidents (Subch. D)', question: 'A child in care sustains a substantial physical injury that a reasonable person would conclude needs treatment by a medical professional. The report to Child Care Regulation is due as soon as possible, but no later than:', options: ['2 hours after the incident', '12 hours after the incident', '24 hours after the incident', '72 hours after the incident'], correct: 2, explanation: '§749.503(a)(2) requires a report to Child Care Regulation as soon as possible, but no later than 24 hours after the incident. Parents must be notified immediately after ensuring the safety of the child, and law enforcement is not a required notification for this incident. Remember that the nature of the injury, not the treatment venue, determines whether it is reportable.' },
      { id: 'p1q15', domain: 'Serious Incidents (Subch. D)', question: 'A 15-year-old in care, with no history of being alleged a trafficking victim and not believed abducted, is missing and has not returned. Under §749.503(a)(10), the report to Child Care Regulation is due no later than:', options: ['6 hours from when the child\'s absence is discovered, if the child is still missing', '2 hours from when the child\'s absence is discovered', '12 hours from when the child\'s absence is discovered', '24 hours from when the child\'s absence is discovered'], correct: 0, explanation: '§749.503(a)(10) (unauthorized absence of a child 13 or older) requires reports to Child Care Regulation, the parent, and law enforcement no later than 6 hours from when the absence is discovered if the child is still missing. The report must be immediate if the child was previously alleged or determined to be a trafficking victim, or the CPA believes the child was abducted or will not return.' },
      { id: 'p1q16', domain: 'Unauthorized Absences (Subch. D)', question: 'A triggered review of a child\'s unauthorized absences is required after three unauthorized absences within a 60-day timeframe. The review must occur as soon as possible, but no later than how long after the third absence?', options: ['10 days', '14 days', '21 days', '30 days'], correct: 3, explanation: '§749.593(a) requires the triggered review as soon as possible, but no later than 30 days after the child\'s third unauthorized absence within a 60-day timeframe (see the definition in §749.501(2)). A regularly scheduled service plan review can serve as the triggered review if it meets §749.595 and occurs within the same 30 days.' },
      { id: 'p1q17', domain: 'Unauthorized Absences (Subch. D)', question: 'After a child returns to the foster home from an unauthorized absence, the foster parent or other appropriate person must conduct a debriefing no later than:', options: ['12 hours after the child\'s return', '24 hours after the child\'s return', '48 hours after the child\'s return', '72 hours after the child\'s return'], correct: 1, explanation: '§749.592(a) requires the debriefing as soon as possible, but no later than 24 hours after the child\'s return. It must cover the circumstances, trauma-informed strategies, the child\'s condition, and what occurred during the absence, and must be documented in the child\'s record (§749.592(c)).' },
      { id: 'p1q18', domain: 'Records (Subch. D)', question: 'How long must a child-placing agency keep a copy of its serious incident reports on file?', options: ['Two years', 'One year', 'Three years', 'Five years'], correct: 0, explanation: '§749.515 requires you to keep a copy of incident reports for two years, and the reports must be easily accessible to Licensing upon request.' },
      { id: 'p1q19', domain: 'Records (Subch. D)', question: 'For how long after a verified foster home is closed must the agency maintain the home\'s records (including homes that never received placements)?', options: ['One year', 'Two years', 'Three years', 'Five years'], correct: 3, explanation: '§749.585(c) requires records for verified foster homes to be kept at least five years after the home is closed, including homes that did not receive placements. By contrast, a foster child\'s record is kept two years after discharge, or until any investigation is resolved if longer (§749.585(b)).' },
      { id: 'p1q20', domain: 'Records (Subch. D)', question: 'Except for annual training records, how long must personnel records be kept after an employee\'s last day on the job?', options: ['Six months, or until an investigation is resolved if shorter', 'One year, or until any investigation involving the employee is resolved, whichever is longer', 'Three years in all cases', 'Five years in all cases'], correct: 1, explanation: '§749.555(b) requires you to keep personnel records for a year after an employee\'s last day on the job, or until any investigation involving the employee is resolved, whichever is longer. Annual training records for current personnel are kept for the last full training year and the current training year (§749.555(a)).' },
      { id: 'p1q21', domain: 'Records (Subch. D)', question: 'Licensing asks to review your archived records. Active records must be available immediately. Archived records must be available for review and reproduction within:', options: ['24 hours', '72 hours', '5 business days', '48 hours'], correct: 3, explanation: '§749.537(a) requires active records to be available for immediate review and reproduction, and §749.537(b) requires archived records to be available within 48 hours.' },
      { id: 'p1q22', domain: 'Administrator Duties (Subch. E)', question: 'When the administrator is absent on a frequent or extended basis, the employee the administrator designates to be responsible for the overall administration of the agency must:', options: ['Be the agency\'s treatment director', 'Hold a master\'s degree in social work', 'Be a Licensed Child-Placing Agency Administrator', 'Be a member of the governing body'], correct: 2, explanation: '§749.637(a) requires the administrator to designate an employee to be responsible for overall administration during frequent or extended absences, and §749.637(b) requires that designee to be a Licensed Child-Placing Agency Administrator as required by Chapter 43 of the Human Resources Code.' },
      { id: 'p1q23', domain: 'Records and Notifications (Subch. D)', question: 'CCR cites a foster home verified by your agency for a safe sleeping deficiency. Within how long after you receive notification of the deficiency must you notify the parents of each child in the care of each of your verified foster homes?', options: ['Five days', '24 hours', '10 days', '30 days'], correct: 0, explanation: '§749.519(a) requires you to notify parents within five days after you receive notification of the deficiency, covering each child in care of each foster home verified by your agency at the time of notification. Safe sleeping deficiencies use Form 2970 (§749.519(c)), and you must keep proof of notification (§749.519(e)).' },
      { id: 'p1q24', domain: 'Agency Staff (Subch. E)', question: 'A person who is on probation and ordered by a court to complete community service hours asks to perform them at your child-placing agency. Under §749.769:', options: ['Yes, if an employee supervises the person at all times', 'Yes, if the person passes the required background checks', 'Yes, but only in positions with no contact with children', 'No, a person may not perform community service at your agency'], correct: 3, explanation: '§749.769 states that a person may not perform community service at your agency. Community service includes service a person must perform because of probation, parole, or a court requirement due to criminal activity.' },
      { id: 'p1q25', domain: 'Child Placement Staff (Subch. E)', question: 'An applicant for a child placement staff position holds a bachelor\'s degree in business (not social work or another human services field). Under Option 2 of §749.673, which documented full-time professional experience is required, other than the alternative of supervised experience?', options: ['Two years of qualifying experience', 'Six months of qualifying experience', 'One year of qualifying experience', 'Three years of qualifying experience'], correct: 0, explanation: '§749.673 Option 2 requires a bachelor\'s degree from an accredited college or university plus two years of documented full-time work experience in a child-placing agency, residential child-care operation, or as a DFPS conservatorship caseworker or foster/adoptive home development worker (or two years under direct supervision with 10 documented monthly conferences per year). Option 1 requires only one year, but needs a master\'s degree or a bachelor\'s in social work or another human services field.' },
      { id: 'p1q26', domain: 'Child Placement Management Staff (Subch. E)', question: 'A candidate for child placement management staff has a bachelor\'s degree in an unrelated field and nine credit hours in courses on family and individual function and interaction. Under Option 3 of §749.675, how much documented full-time experience is required?', options: ['One year', 'Two years', 'Three years', 'Five years'], correct: 2, explanation: '§749.675 Option 3 requires a bachelor\'s degree from an accredited college or university, nine credit hours in courses focused on family and individual function and interaction, and three years of documented full-time experience in a child-placing agency, a residential child-care operation, or as a CPS caseworker for DFPS conducting assessments, service planning, or case management. Field placement or practicum experience may not be counted.' },
      { id: 'p1q27', domain: 'Training (Subch. F)', question: 'Each child placement staff, child placement management staff, executive director, treatment director, and CPA administrator must complete at least how many hours of annual training?', options: ['8 hours', '10 hours', '12 hours', '15 hours'], correct: 3, explanation: '§749.825(a) requires at least 15 hours of annual training for these employees, and §749.825(b) requires at least one hour on preventing, recognizing, and reporting child abuse, neglect, and exploitation. The CPA must track annual training consistently by hire date, calendar year, or fiscal year (§749.825(c)).' },
      { id: 'p1q28', domain: 'Training (Subch. F)', question: 'Within how many days after starting the job must a new CPA administrator, treatment director, child placement staff, child placement management staff, or full-time professional service provider complete the new employee training (at least two hours plus EBI training)?', options: ['10 days', '30 days', '60 days', '90 days'], correct: 1, explanation: '§749.823(a) requires these employees to complete, within 30 days after starting the job, at least two hours of training on normalcy, trauma informed care, and preventing the spread of communicable diseases, plus emergency behavior intervention training consistent with the CPA\'s EBI curriculum.' },
      { id: 'p1q29', domain: 'Caregiver Training (Subch. F)', question: 'Before a CPA places a child in a foster home, at least one foster parent must complete which training under §749.803(a)?', options: ['Four hours of general caregiver training and six hours of emergency behavior intervention training (plus safe sleeping training if the child is under two)', 'Eight hours of general caregiver training and four hours of emergency behavior intervention training', 'Six hours of general caregiver training and six hours of emergency behavior intervention training', 'Four hours of general caregiver training and two hours of emergency behavior intervention training'], correct: 0, explanation: '§749.803(a) requires four hours of general caregiver training, six hours of EBI training, and safe sleeping training if the home will care for a child younger than two. Other caregivers, including a second foster parent, have 90 days after placement (§749.803(b)). The CPA may decide not to require EBI training if it does not apply to the ages of the children and services provided (§749.803(f)).' },
      { id: 'p1q30', domain: 'Caregiver Training (Subch. F)', question: 'One foster parent must be certified in pediatric first aid and pediatric CPR before the home is verified. A second foster parent or other caregiver must be certified within how long?', options: ['30 days after the CPA verifies the home', '60 days after the CPA verifies the home', '90 days after the CPA verifies the home', '180 days after the CPA verifies the home'], correct: 2, explanation: '§749.805(a) requires one foster parent to be certified in pediatric first aid and CPR before the CPA issues the verification, and other caregivers, including a second foster parent, within 90 days after the CPA verifies the home. Certificates must carry an expiration date and be renewed by that date (§749.831(e)).' },
    ],
  },
  {
    id: 'lcpaa-exam-2',
    number: 2,
    title: 'LCPAA Practice Exam 2',
    description: 'Foundational II: foster home screening and verification, health and safety, home management, admission and placement, and service planning and discharge (Subchapters G-K).',
    questions: [
      { id: 'p2q1', domain: 'Foster Home Screenings (Subch. G)', question: 'A foster home screening must include one individual interview with each prospective foster parent and each household member living in the home full or part time who is at least what age?', options: ['3 years old', '6 years old', '10 years old', '14 years old'], correct: 0, explanation: '§749.903(a)(1) requires one individual interview with each prospective foster parent and each household member at least three years old living in the home full or part time. The screening also requires a joint interview of the prospective foster parents, an in-home family group interview with all household members present, and interviews with adult children not living in the home (§749.903(a)(2)-(4)).' },
      { id: 'p2q2', domain: 'Foster Home Screenings (Subch. G)', question: 'In addition to the required interviews, a foster home screening must include how many additional references?', options: ['Two additional references, at least one from a relative', 'Three additional references, at least one from a non-relative', 'Three additional references, all from non-relatives', 'Five additional references, at least one from an employer'], correct: 1, explanation: '§749.903(a)(5) requires three additional references, including at least one from a non-relative.' },
      { id: 'p2q3', domain: 'Foster Home Screenings (Subch. G)', question: 'CCR background checks must be conducted and assessed on each prospective foster parent and on any non-client who regularly or frequently stays at or is present in the home and is at least what age (excluding children or young adults in care)?', options: ['10 years old', '12 years old', '14 years old', '16 years old'], correct: 2, explanation: '§749.901(c)(6)(A) requires CCR criminal history and central registry background checks to be conducted and assessed on each prospective foster parent and on any non-client who is 14 years old or older who regularly or frequently stays at or is present in the home, excluding children or young adults in care. The CPA must not include CCR background check results in the home screening document (§749.901(c)(6)(D)).' },
      { id: 'p2q4', domain: 'Foster Home Verification (Subch. G)', question: 'A foster family moves from one residence to another and the CPA issues a temporary foster home verification. How long is it valid?', options: ['Three months, and it can be extended once', 'Six months, and it cannot be extended', 'Six months, and it can be extended 30 days if an inspection is pending', 'Twelve months, and it can be extended once'], correct: 1, explanation: '§749.925(b) states that a temporary verification is valid for a maximum of six months from the date it was issued and cannot be extended. The CPA must inspect the new residence within 30 days after the move (§749.925(c)).' },
      { id: 'p2q5', domain: 'Foster Home Verification (Subch. G)', question: 'A family moves to a new residence and holds a temporary verification. The CPA completes the 30-day inspection of the new residence. May the CPA place a NEW child in the home before issuing the non-expiring verification?', options: ['Yes, once the 30-day inspection is complete', 'Yes, if child placement management staff approve the placement', 'No, not until the non-expiring verification is issued', 'Yes, if the home had no deficiencies at its prior address'], correct: 2, explanation: '§749.925(e) states the CPA cannot place a new child in the care of the home until the non-expiring verification is issued, and §749.925(d) requires the CPA to ensure the home meets all requirements of the chapter before issuing it.' },
      { id: 'p2q6', domain: 'Foster Home Verification (Subch. G)', question: 'A CPA receives a written request for background information about a current or previous foster home from another CPA conducting a home screening. By when must the information be released?', options: ['By the 2nd day after receiving the request', 'By the 5th day after receiving the request', 'By the 7th day after receiving the request', 'By the 10th day after receiving the request'], correct: 3, explanation: '§749.931(c) requires release by the 10th day after receiving the written request, including informing the requesting agency of any pending investigations and unresolved deficiencies. The outcomes and resolutions must then be released by the 10th day after those matters are completed.' },
      { id: 'p2q7', domain: 'Foster Home Verification (Subch. G)', question: 'A CPA verifies a new foster home. Within how long must it submit that information to Child Care Regulation?', options: ['Two business days', 'Five business days', 'Ten business days', '30 days'], correct: 0, explanation: '§749.933(a) requires the CPA to submit information to CCR within two business days after verifying a new home. The same deadline applies to temporary or provisional verifications, placing a home on or removing it from inactive status, changing verification conditions, and closing a home (with the reason).' },
      { id: 'p2q8', domain: 'Foster Home Verification (Subch. G)', question: 'A foster home closes. The closing summary, which must include the reason for closure and any pending investigations or unresolved deficiencies, must be completed by:', options: ['The 5th day after the home closes', 'The 10th day after the home closes', 'The 15th day after the home closes', 'The 20th day after the home closes'], correct: 3, explanation: '§749.937(d)(4) requires a closing summary to be completed by the 20th day after a home is closed. A transfer summary, by contrast, must be completed by the 10th day after the CPA receives a written request to transfer (§749.937(c)(2)).' },
      { id: 'p2q9', domain: 'Capacity and Supervision (Subch. G)', question: 'A foster home that cares for infants may care for up to six children, with a maximum of how many infants and no more than how many children less than six years old?', options: ['Two infants; no more than four children less than six years old', 'Three infants; no more than four children less than six years old', 'Two infants; no more than three children less than six years old', 'Four infants; no more than five children less than six years old'], correct: 0, explanation: '§749.951(a)(1) allows up to six children if the home cares for infants, with a maximum of two infants and no more than four children less than six years old. An infant is a child from birth through 17 months (§749.43(39)).' },
      { id: 'p2q10', domain: 'Capacity and Supervision (Subch. G)', question: 'To allow a foster home to care for seven or eight children, the CPA must:', options: ['Complete the CCR Foster Family Home Capacity Exception Form and request and obtain a variance from CCR', 'Obtain the written approval of the CPA administrator only', 'Submit a waiver request based on economic reasons', 'Complete a new home screening and notify CCR within two days'], correct: 0, explanation: '§749.953 permits seven or eight children as recommended by the CPA and approved by CCR; the CPA must complete the CCR Foster Family Home Capacity Exception Form and request and obtain a variance from CCR. Under §749.951(c), capacity counts children in care plus adopted and biological children, respite and daycare children, and young adults in care.' },
      { id: 'p2q11', domain: 'Respite Care (Subch. G)', question: 'After a child in care has been in respite care for how long must the CPA check whether respite is still the best option and make a plan with a timeframe for the child to return to the home or move to a new placement?', options: ['14 days', '30 days', '45 days', '60 days'], correct: 3, explanation: '§749.975(d) requires this review and plan after the child has been in respite care for 60 days. Before respite starts, the CPA must inform the parent and explain the plan to the child, and child placement management staff must approve the respite and confirm no conflict of care (§749.975(a)-(b)).' },
      { id: 'p2q12', domain: 'Health and Safety (Subch. H)', question: 'A foster home must practice its disaster and emergency plan with children in care within:', options: ['72 hours of placement', 'The first month of placement', 'The first 90 days of placement', 'The first six months of placement'], correct: 1, explanation: '§749.1009(c) requires the home to practice the emergency plan with children in care within the first month of placement. The CPA that verified the home must also review and evaluate the plan annually with all caregivers and children in care (§749.1009(b)).' },
      { id: 'p2q13', domain: 'Weapons and Firearms (Subch. H)', question: 'Which statement about firearms in foster homes is consistent with §749.1033 and §749.1035?', options: ['The CPA must keep a list of the make and model of each firearm in the home record', 'The CPA may not require the home to disclose the specific types of firearms stored or present in the home', 'The CPA must require the home to notify it of any change in the types of firearms present', 'The CPA must inspect firearm storage at every quarterly supervisory visit'], correct: 1, explanation: '§749.1033(b) and §749.1035(d)-(e) prohibit a CPA from requiring a home to disclose specific types of firearms or to notify the CPA of changes in the types of firearms. The CPA must still ask about weapons at screening, document whether they are present and the precautions taken, and discuss storage in the annual evaluation (§749.1035(a)-(c)).' },
      { id: 'p2q14', domain: 'Sleeping Space (Subch. H)', question: 'With approval from child placement management staff, up to how many children may share a sleeping space?', options: ['Two', 'Three', 'Four', 'Six'], correct: 2, explanation: '§749.1051(a) allows up to four children to share a sleeping space with approval from child placement management staff, who must document in the service plan that there is no known risk of harm (§749.1051(c)). Staff may not approve an infant to share a sleeping surface (§749.1051(d)), and a child over five must not share a sleeping room with a child of the opposite sex (§749.1051(e)).' },
      { id: 'p2q15', domain: 'Pools and Water Activities (Subch. H)', question: 'A swimming pool at a foster home must have a barrier on all sides that is at least how high? (An exterior wall of the home may serve as one side.)', options: ['Three feet', 'Four feet', 'Five feet', 'Six feet'], correct: 1, explanation: '§749.1061(a) requires a barrier on all sides at least four feet high. Gates must be secured with a safety device that is locked when the pool or hot tub is not in use (§749.1061(b)), and doors from the home to the pool area need a door alarm or an adult-only lock (§749.1061(d)).' },
      { id: 'p2q16', domain: 'Pools and Water Activities (Subch. H)', question: 'When four or more children over the age of two are participating in swimming activities, how many caregivers must be present supervising the activity area?', options: ['At least one', 'At least two', 'At least three', 'At least four'], correct: 1, explanation: '§749.1065(b) requires at least two caregivers when four or more children over age two are swimming. Under §749.1065(a) there must be one caregiver for each child under two, and under (c) one caregiver for each non-ambulatory child or child subject to seizures unless a licensed physician documents that special precautions are not needed.' },
      { id: 'p2q17', domain: 'Foster Home Management (Subch. I)', question: 'Child placement staff must conduct supervisory visits inside the foster home at least how often?', options: ['Every month', 'Every two months', 'Every three months', 'Every six months'], correct: 2, explanation: '§749.1105(a)-(b) requires supervisory visits at least every three months, and the visits must happen inside the home. Within 12 months, two visits must be unannounced and one must have all household members present, and both foster parents must be present for one visit every six months (§749.1105(c)).' },
      { id: 'p2q18', domain: 'Foster Home Management (Subch. I)', question: 'Within a 12-month period, how many of a foster home\'s supervisory visits must be unannounced?', options: ['None', 'One', 'Two', 'Four'], correct: 2, explanation: '§749.1105(c)(1) requires two of the supervisory visits within a 12-month period to be unannounced. Additionally, one visit must have all household members present and, if there are two foster parents, both must be present for one visit every six months.' },
      { id: 'p2q19', domain: 'Foster Home Management (Subch. I)', question: 'A foster home on inactive status wants to return to active status and care for a child. Before a child can be placed, the CPA must:', options: ['Make a supervisory visit to ensure the home meets the chapter and confirm background checks are active in Eligible or Conditional status', 'Wait 90 days after the reactivation request before placing a child', 'Complete a brand-new foster home screening and re-verify the home', 'Notify CCR within 30 days after the placement is made'], correct: 0, explanation: '§749.1107(d)-(e) requires a supervisory visit to ensure the home meets the laws and rules in the chapter, and background checks must be active and in an Eligible or Conditional status before placement. The CPA must document this (§749.1109(2)(B)) and inform CCR of the status change via an Agency Home Report Form (§749.1107(b)), within two business days (§749.933(a)(3)).' },
      { id: 'p2q20', domain: 'Foster Home Management (Subch. I)', question: 'Which of the following automatically invalidates a foster home\'s verification under §749.1101(c)?', options: ['A foster parent renews a pediatric CPR certification', 'The family repaints a child\'s bedroom', 'A foster parent changes employers with no change in household schedule', 'A change in the types of services the home will provide'], correct: 3, explanation: '§749.1101(c) lists changes that automatically invalidate verification: marriage, divorce, separation, death, birth, or other change in household composition; address or location changes; changes in the number of children the home may have; changes in the ages or sex of children authorized; and changes in the types of services provided. A new or temporary verification must be given after the CPA checks compliance (§749.1101(b)).' },
      { id: 'p2q21', domain: 'Admission and Placement (Subch. J)', question: 'The CPA must provide prospective caregivers with a child\'s initial admission information within how long after the date of admission?', options: ['24 hours', '48 hours', '72 hours', '5 days'], correct: 0, explanation: '§749.1203(b) requires the CPA to provide prospective caregivers with the child\'s initial admission information within 24 hours after the date of admission. The information includes health status, high-risk behaviors, suicide risk screening results, and known contraindications to restraint (§749.1203(a)).' },
      { id: 'p2q22', domain: 'Admission and Placement (Subch. J)', question: 'The CPA must complete a child\'s admission assessment within how long after the date of admission?', options: ['5 days', '7 days', '10 days', '15 days'], correct: 3, explanation: '§749.1205(a) requires the admission assessment within 15 days after the date of admission. Under §749.1205(c), it must be given to the caregivers and professional service providers working with the child within five days after the assessment is finished.' },
      { id: 'p2q23', domain: 'Admission and Placement (Subch. J)', question: 'Within seven days after admission, the CPA must provide an admission orientation to each child in care who is at least what age?', options: ['3 years old', '5 years old', '7 years old', '10 years old'], correct: 1, explanation: '§749.1207(a) requires an orientation within seven days after admission for each child at least five years old, delivered in a way that is easy to understand, in the child\'s main language and communication method, and suitable for the child\'s age. The orientation includes the CPA\'s child-care policies (§749.1207(b)).' },
      { id: 'p2q24', domain: 'Admission and Placement (Subch. J)', question: 'For non-emergency placements, a child in care must visit the foster home at least once before placement if the child is at least what age?', options: ['Newborn (any age)', 'Six months', 'Two years', 'Five years'], correct: 1, explanation: '§749.1211(b) requires a pre-placement visit for non-emergency placements of children six months of age or older. During the visit, child placement staff observe the interaction with household members, and there must be time afterward for the child and foster parents to each meet privately with staff (§749.1211(c)-(d)).' },
      { id: 'p2q25', domain: 'Admission and Placement (Subch. J)', question: 'Child placement staff must have monthly in-person visits with each child in care. What portion of those visits must occur in the foster home?', options: ['Every visit', 'One visit each quarter', 'At least half of the visits', 'None; visits may all occur at the CPA office'], correct: 2, explanation: '§749.1213(b)(1) requires at least half of the monthly visits to occur in the foster home. Visits must also provide an opportunity to meet privately and for the child to discuss how the placement is working out (§749.1213(b)(3)).' },
      { id: 'p2q26', domain: 'Service Planning (Subch. K)', question: 'An initial service plan, including the signatures of the people who helped develop it, must be finished within how long after the child is admitted?', options: ['15 days', '30 days', '45 days', '60 days'], correct: 3, explanation: '§749.1233(e) requires the initial service plan to be finished within 60 days after the child is admitted, with the signatures of the people who helped develop it. The plan is developed by a service planning team using the admission assessment (§749.1233(a)).' },
      { id: 'p2q27', domain: 'Service Planning (Subch. K)', question: 'The service planning team must check and update a child\'s service plan at least every:', options: ['90 days', '120 days', '180 days', '12 months'], correct: 2, explanation: '§749.1233(f) requires the team to review and update the service plan at least every 180 days after the date of the last service plan, considering the child\'s progress and new needs.' },
      { id: 'p2q28', domain: 'Service Planning (Subch. K)', question: 'A child receiving treatment services for an emotional disorder is admitted from a setting that is NOT a regulated residential child-care operation. The CPA must obtain a written, dated, and signed psychosocial assessment (or equivalent) within:', options: ['Six months after the date of admission', 'Fourteen months after the date of admission', 'Ninety days after the date of admission', 'Twelve months after the date of admission'], correct: 0, explanation: '§749.1235 requires the assessment within six months after admission if the child is not coming from another regulated residential child-care operation, and within 14 months if the child is coming from one. It applies to treatment services for emotional disorders, autism spectrum disorder, or intellectual disabilities.' },
      { id: 'p2q29', domain: 'Discharge and Transfer (Subch. K)', question: 'If the service planning team decides a child in care should be told in advance about a discharge or transfer, the CPA must inform the child at least how long before the date?', options: ['24 hours', 'Two days', 'Three days', 'Four days'], correct: 3, explanation: '§749.1251(a)(3) requires the CPA to inform the child at least four days before the date of discharge or transfer if the service planning team decides the child should be told in advance. The CPA must consult the team and follow its recommendation (§749.1251(a)(2)).' },
      { id: 'p2q30', domain: 'Discharge and Transfer (Subch. K)', question: 'The CPA must provide a discharge or transfer summary to the receiving placement or caregiver within how long after the child is discharged or transferred?', options: ['5 days', '7 days', '10 days', '15 days'], correct: 3, explanation: '§749.1251(d) requires the discharge or transfer summary within 15 days after the discharge or transfer. It includes services provided, current behaviors and needs, upcoming appointments, transition resources, and the child\'s background information, including unresolved incidents or investigations.' },
    ],
  },
  {
    id: 'lcpaa-exam-3',
    number: 3,
    title: 'LCPAA Practice Exam 3',
    description: 'Applied: scenario-based questions across Chapter 749 that test the best action a child-placing agency administrator should take under the rules.',
    questions: [
      { id: 'p3q1', domain: 'Administration (Subch. C)', question: 'You are the CPA administrator. Your agency administrator resigns without notice and you have no back-up administrator. What is the correct course of action?', options: ['Notify Licensing at least 30 days before the vacancy takes effect and wait for the next permit anniversary to name a replacement', 'Notify Licensing within 15 days and name any senior caseworker as acting administrator indefinitely', 'Notify your Licensing Representative in writing within two days, and obtain a licensed child-care administrator within 60 days of the vacancy', 'Notify Licensing only if the vacancy lasts longer than 60 days'], correct: 2, explanation: '§749.153(a)(3)(A) requires written notice to your Licensing Representative as soon as possible, but no later than two days after the administrator position becomes vacant. Under §749.154, with no back-up administrator you have 60 days from the vacancy to obtain a licensed child-care administrator before Licensing can cite you; §749.151(1) requires a designated full-time administrator while operating.' },
      { id: 'p3q2', domain: 'Personnel Policies (Subch. C)', question: 'A new caseworker tells you she suspects a foster child is being abused and asks whether she should wait for your approval before calling. What do you tell her?', options: ['She must report directly to the Texas Abuse and Neglect Hotline herself; she cannot delegate the report, and you cannot require her to get your approval first', 'She should report to you first, and you will decide whether the Hotline needs to be called', 'She may ask her supervisor to make the report, as long as the supervisor documents it', 'She must wait for child placement management staff to confirm the suspicion before reporting'], correct: 0, explanation: '§749.105(6) requires employees to report suspected abuse, neglect, or exploitation directly to the Texas Abuse and Neglect Hotline. An employee may not delegate the responsibility, and the agency may not require an employee to seek approval to file a report or to notify the agency that a report was made. See also §749.607(2).' },
      { id: 'p3q3', domain: 'Branch Offices (Subch. C)', question: 'You are closing a branch office because of a lease issue. The closure is NOT related to any corrective or adverse action against your agency. What may you do with the foster homes the branch supervised?', options: ['Close all of them, because homes cannot be transferred between offices', 'Transfer them only after updating each foster home study and rerunning every background check', 'Transfer them only after Licensing re-verifies each home', 'Transfer them to the main office or another branch office without updating the foster home screening'], correct: 3, explanation: '§749.307(b) allows you to transfer the homes to the main office or another branch office without updating the foster home screening when the closure is not related to a corrective or adverse action. If the closure IS related to a corrective or adverse action, §749.307(a) requires you to close the homes or transfer them with an updated study, background checks within the last 24 months, and an amended verification certificate.' },
      { id: 'p3q4', domain: 'Serious Incidents (Subch. D)', question: 'At 9 p.m. a foster parent tells you a 15-year-old in care has not returned home and cannot be located. The child has never been alleged to be a trafficking victim and you do not believe the child was abducted. If the child is still missing, by when must the absence be reported to Child Care Regulation, the parent, and law enforcement?', options: ['Within 2 hours of notifying law enforcement', 'No later than 6 hours from when the child\'s absence is discovered', 'Only if the child remains missing after 24 hours', 'Within 12 hours after the child was last seen'], correct: 1, explanation: '§749.503(a)(10) requires reports to CCR, the parent, and law enforcement no later than 6 hours from when the absence of a child 13 or older is discovered, if the child is still missing. The report must be immediate if the child was previously alleged or determined to be a trafficking victim, or you believe the child was abducted or will not return. If the child returns before the timeframe, you must document within 24 hours (§749.503(c)). Reports go to the Texas Abuse and Neglect Hotline (§749.509(a)).' },
      { id: 'p3q5', domain: 'Unauthorized Absences (Subch. D)', question: 'A foster child has had three unauthorized absences in 45 days. As the administrator, what must your agency do?', options: ['Nothing further, because a debriefing after each absence satisfies the rules', 'Hold a triggered review no later than 30 days after the third absence with the child, the foster parent, and child placement staff, after notifying the parent at least two weeks in advance', 'Hold a triggered review within 90 days with only child placement management staff participating', 'Discharge the child and complete the review after the child leaves the home'], correct: 1, explanation: '§749.593(a) requires a triggered review as soon as possible, but no later than 30 days after the third unauthorized absence within a 60-day timeframe. Under §749.594, the child, foster parent, and child placement staff must participate and the parent must be notified at least two weeks before. The review must produce a written plan to reduce the absences (§749.595(4)).' },
      { id: 'p3q6', domain: 'Records and Notifications (Subch. D)', question: 'CCR cites one of your foster homes for a safe sleeping deficiency involving an infant\'s sleep environment. What must your agency do?', options: ['Notify only the parents of the child involved, within 30 days', 'Notify only the parents of children in that home, within 24 hours', 'Notify every parent by telephone within 24 hours, with no written record required', 'Within five days, notify the parent of each child in the care of each foster home your agency has verified, using Form 2970, and keep proof of the notice'], correct: 3, explanation: '§749.517 and §749.519(a) require notice within five days after you receive notification of the deficiency, to the parents of each child in the care of each foster home verified by your agency, including children who may not have been in care on the day of the incident. Safe sleeping deficiencies use Form 2970 (§749.519(c)), and you must keep proof of the written notice (§749.519(e)).' },
      { id: 'p3q7', domain: 'Adoptive Home Screening (Subch. S)', question: 'An approved adoptive family has waited 14 months for a placement with no update to its adoptive home screening. The family is not also a foster home verified by your agency. What is required?', options: ['Update the screening now; updates are due every 12 months and after a major life change, including documentation of a visit with all household members present within the 90 days before the update is approved', 'Nothing; updates are required only every 24 months', 'Nothing; updates are required only after a major life change', 'Update the screening only if the family now wants to adopt a different child'], correct: 0, explanation: '§749.3633(a)-(b) requires an adoptive home screening update every 12 months and after a major life change, and the update must document at least one visit to the home with all household members present within the 90 days before child placement management staff approve it. No update is required if the home is also a foster home verified by your agency (§749.3633(c)). Adopting another child also requires an update (§749.3637).' },
      { id: 'p3q8', domain: 'Child Placement Staff (Subch. E)', question: 'You want to hire a caseworker whose only credential is a bachelor\'s degree in business with no relevant work history. Which arrangement meets the child placement staff qualifications?', options: ['One year of work under direct supervision, with six documented conferences', 'No experience is required if the person completes orientation and new employee training', 'Two years of documented full-time qualifying experience, or two years working under direct supervision of child placement management staff with 10 documented monthly face-to-face case-related conferences each year', 'One year of documented full-time experience in any child-care setting'], correct: 2, explanation: '§749.673 Option 2 requires a bachelor\'s degree plus two years of qualifying full-time experience, or two years of direct supervision by child placement management staff consisting of 10 documented monthly, face-to-face, individual, case-related conferences over each annual period. The one-year path in Option 1 requires a master\'s degree or a bachelor\'s degree in social work or another human services field.' },
      { id: 'p3q9', domain: 'Treatment Director (Subch. E)', question: 'Your agency has 80 children in foster care, and 26 of them receive treatment services. Are you required to have a treatment director?', options: ['Yes, because any agency that provides treatment services must have a treatment director', 'Yes, because more than 25 children receive treatment services', 'Yes, but a part-time treatment director is sufficient', 'No, because a treatment director is required only when treatment services go to 30 or more children, or to more than 50% of children in care'], correct: 3, explanation: '§749.721 requires a full-time treatment director if you provide treatment services to 30 or more children at any one time, or to more than 50% of the children in your care. With 26 of 80 children (32.5%), neither threshold is met.' },
      { id: 'p3q10', domain: 'Administrator Duties (Subch. E)', question: 'You will be on extended medical leave for three months. Which plan satisfies the rules for who runs the agency in your absence?', options: ['Designate the lead child placement staff member, regardless of licensure', 'Designate the treatment director, regardless of licensure', 'Designate an employee who is a Licensed Child-Placing Agency Administrator to be responsible for overall administration of the agency', 'No designation is needed as long as you can be reached by phone'], correct: 2, explanation: '§749.637(a)-(b) requires the administrator to designate an employee responsible for overall administration when absent on a frequent or extended basis, and the designee must be a Licensed Child-Placing Agency Administrator. The administrator is otherwise responsible for daily supervision of all offices (§749.635(1)).' },
      { id: 'p3q11', domain: 'Caregiver Training (Subch. F)', question: 'A couple is ready for their first placement, a 20-month-old. The husband has completed four hours of general caregiver training, six hours of EBI training, and safe sleeping training. His wife has completed none. May you place the child?', options: ['Yes; at least one foster parent must complete the training before placement, and the second foster parent must complete it within 90 days after placement', 'No; both foster parents must complete all training before any placement', 'Yes; the second foster parent has 12 months to complete the training', 'No; the husband must complete eight hours of general caregiver training first'], correct: 0, explanation: '§749.803(a)-(b) requires at least one foster parent to complete four hours of general caregiver training, six hours of EBI training, and safe sleeping training (because the child is younger than two) before placement; other caregivers, including the second foster parent, have 90 days after placement. One foster parent must also hold pediatric first aid and CPR certification before verification (§749.805(a)).' },
      { id: 'p3q12', domain: 'Employee Training (Subch. F)', question: 'A caseworker who handles only adoption services responsibilities started 10 days ago. Must she complete the new employee training (two hours plus EBI training) within 30 days of starting?', options: ['Yes; all child placement staff must complete it regardless of duties', 'No; an employee who only handles adoption services responsibilities does not have to complete any new employee training', 'Yes, but only the two-hour portion and not EBI training', 'No, but she must complete the training within 90 days instead'], correct: 1, explanation: '§749.823(b) states that an employee who only handles adoption services responsibilities does not have to complete any new employee training. She still must complete orientation before beginning job duties (§749.821) and annual training (§749.825).' },
      { id: 'p3q13', domain: 'Assessment Services (Subch. T)', question: 'Your assessment services program admits a 4-year-old on June 1. Absent an approved extension, by when must the assessment report be completed?', options: ['Within 10 days (June 11)', 'Within 15 days (June 16)', 'Within 45 days (July 16)', 'Within 30 days (July 1)'], correct: 3, explanation: '§749.3893(b)(1) requires the assessment report within 30 days after admission if the child is younger than five (45 days if five or older). With the parent\'s approval you may extend the deadline an additional 15 days and must document the need in the child\'s record (§749.3893(c)). The 10-day deadline in §749.3861 is for the individual plan for the assessment, not the report.' },
      { id: 'p3q14', domain: 'Foster Home Screenings (Subch. G)', question: 'During a foster home screening you learn that a 15-year-old niece of the prospective foster parents, who is not a child in care, lives in the home. What background check requirement applies to her?', options: ['None, because background checks apply only to adults', 'CCR background checks must be conducted and assessed because she is a non-client at least 14 years old who regularly or frequently stays in the home', 'Checks are required only if she is 16 or older', 'Checks are required only if she has a prior juvenile record'], correct: 1, explanation: '§749.901(c)(6)(A)(ii) requires CCR background checks to be conducted and assessed on any non-client at least 14 years old who regularly or frequently stays at or is present in the home (excluding children or young adults in care). She must also receive an individual interview as a household member at least three years old (§749.903(a)(1)).' },
      { id: 'p3q15', domain: 'Kinship Foster Homes (Subch. W)', question: 'A kinship foster home with one caregiver is caring for three infants and two of the caregiver\'s own children. DFPS asks the CPA to place a sixth child, a toddler. Under Subchapter W, what applies?', options: ['The home may care for up to six children regardless of the number of caregivers or ages of the children, counting its own, adopted, respite, and daycare children, so no capacity exception is needed', 'The placement is prohibited because a home may care for only two infants', 'The placement is prohibited because a single-caregiver home may care for only four children', 'The placement is allowed only after Form 4003 and a variance from CCR'], correct: 0, explanation: '§749.4517(a) allows a kinship foster home to care for up to six children regardless of the number of caregivers or ages of the children, counting kinship foster children and adopted and biological children, respite children, and daycare children. Form 4003 and a CCR variance are needed only for seven or eight children (§749.4517(b)). The two-infant limit in §749.951(a)(1) applies to non-kinship foster homes.' },
      { id: 'p3q16', domain: 'Capacity (Subch. G)', question: 'A foster home currently has six children in the home, counting the foster parents\' biological child. A caseworker proposes placing a seventh child. What is required?', options: ['Nothing, because capacity counts only children in foster care and the biological child is excluded', 'Only approval from child placement management staff', 'The CPA must complete the CCR Foster Family Home Capacity Exception Form and request and obtain a variance from CCR', 'A waiver based on economic hardship'], correct: 2, explanation: '§749.951(c) counts children in care, adopted and biological children living in the home, respite children, daycare children, and young adults in care toward capacity. Under §749.953, caring for seven or eight children requires the CPA\'s recommendation, the CCR Foster Family Home Capacity Exception Form, and a variance from CCR.' },
      { id: 'p3q17', domain: 'Weapons and Firearms (Subch. H)', question: 'A foster parent tells you she keeps rifles in a locked gun safe. During the annual evaluation, a supervisor wants a written list of the make, model, and caliber of each firearm. What is correct?', options: ['The CPA must discuss whether firearms are present and how they are stored, but may not require the home to disclose the specific types of firearms', 'The CPA must require the list so it can verify safe storage', 'The CPA may require the list as long as it is kept confidential', 'Locked firearms do not need to be discussed at all during the annual evaluation'], correct: 0, explanation: '§749.1035(c) requires the annual evaluation to include a discussion of whether the home has weapons, firearms, explosive materials, or projectiles and how they are stored. §749.1033(b) and §749.1035(d) prohibit the CPA from requiring disclosure of the specific types of firearms, and §749.1035(e) prohibits requiring notice of changes in the types of firearms.' },
      { id: 'p3q18', domain: 'Pools and Water Activities (Subch. H)', question: 'A foster home pool has a four-foot barrier on all sides (the house wall forms one side). A door from the house to the pool area has an ordinary lock that a child can open and no door alarm. What must you require?', options: ['Nothing, because a four-foot barrier alone is sufficient', 'Replace the barrier with a six-foot fence', 'A lifeguard whenever children are in the house', 'A door alarm, or a lock that only an adult can access and operate (unless the fire authority determines the lock violates fire code and that determination is kept in the home record)'], correct: 3, explanation: '§749.1061(d) requires any door leading from the home to an area with a pool, hot tub, or body of water to have a door alarm or a lock that is accessible and operational only by an adult, unless the fire authority determines the lock violates the fire code and the CPA keeps that determination in the home record. The four-foot barrier on all sides, with the house wall allowed as one side, satisfies §749.1061(a).' },
      { id: 'p3q19', domain: 'Pools and Water Activities (Subch. H)', question: 'A foster parent plans to take an 8-year-old child in care who cannot swim to a lake. What must the caregiver do?', options: ['Allow swimming without a flotation device if the caregiver stays within arm\'s reach', 'Make sure the child wears a properly fitted and fastened U.S. Coast Guard-approved personal flotation device (Type I, II, or III, or a buoyancy level of 70 or above)', 'Keep the child out of any water unless a certified lifeguard is present', 'Allow inflatable arm bands as long as the child is in sight'], correct: 1, explanation: '§749.1063(d) requires a child who is unable to swim to wear a personal flotation device that is U.S. Coast Guard-approved (Type I, II, or III, or buoyancy level of 70 or above) and properly fitted and fastened. Caregivers must also assess swimming skills before the child enters the water, and the CPA must document how the skills were checked (§749.1063(e)).' },
      { id: 'p3q20', domain: 'Foster Home Management (Subch. I)', question: 'A foster home you placed on inactive status wants to resume taking placements next week. What must you do before a child is placed?', options: ['Notify CCR within 30 days after the placement; no visit is required', 'Complete a full new foster home screening and re-verify the home', 'Make a supervisory visit to confirm the home meets the rules, confirm background checks are active in Eligible or Conditional status, document this, and report the status change to CCR on an Agency Home Report Form', 'Nothing, because inactive homes remain fully verified'], correct: 2, explanation: '§749.1107(b), (d), and (e) require informing CCR with an Agency Home Report Form, a supervisory visit before placement, and active background checks in Eligible or Conditional status. The CPA must document the verification before a child is placed (§749.1109(2)(B)), and CCR must be informed within two business days (§749.933(a)(3)).' },
      { id: 'p3q21', domain: 'Foster Home Management (Subch. I)', question: 'Your foster parents tell you a cousin plans to move into the home next month. What must you do?', options: ['Nothing until the cousin has lived in the home for 30 days', 'Run the background checks only after the cousin moves in', 'Ask about the cousin at the next regular quarterly supervisory visit', 'Ensure the cousin completes the necessary background checks and evaluate the cousin\'s impact on the foster family and each child in care before the cousin moves in'], correct: 3, explanation: '§749.933(c) requires the CPA to ensure a new, unrelated household member has completed necessary background checks and to evaluate the individual\'s impact on the foster family and each child in care before the individual moves into the home. A change in household composition also invalidates the verification (§749.1101(c)(1)) and requires a screening addendum (§749.901(b)).' },
      { id: 'p3q22', domain: 'Admission and Placement (Subch. J)', question: 'You are planning a non-emergency placement of a 3-year-old. What must happen before placement?', options: ['No pre-placement visit is needed for children under five', 'The child must visit the home at least once, child placement staff must observe the child with household members, and there must be time afterward for the child and foster parents to each meet privately with staff', 'The foster parents must visit the child\'s current placement instead of the child visiting the home', 'A pre-placement visit is required only if the child asks for one'], correct: 1, explanation: '§749.1211(b)-(d) requires a pre-placement visit to the home for non-emergency placements of children six months or older, observation of the interaction between the child and household members, and time between the visit and placement for the child and foster parents to meet privately with child placement staff. Staff must also talk to the child about why the child is being placed (§749.1211(a)(2)).' },
      { id: 'p3q23', domain: 'Admission and Placement (Subch. J)', question: 'A 13-year-old is referred to your transitional living program as a non-emergency admission. May you admit the child?', options: ['No; a child must be at least 14 years old to be admitted to a transitional living program as a non-emergency admission', 'Yes, if the parent gives written consent', 'Yes, if child placement management staff approve the admission', 'Yes, if the child will turn 14 within six months'], correct: 0, explanation: '§749.1201(c) allows a child at least 14 years old, or a young adult, to be admitted to a CPA\'s transitional living program as a non-emergency admission, and §749.65(a) makes 14 the minimum eligibility age for a transitional living program. No exception based on parent consent or approval is in the rules.' },
      { id: 'p3q24', domain: 'Service Planning (Subch. K)', question: 'Your service planning team finalizes a child\'s service plan on a Tuesday. By when must copies be provided to the child, the caregivers, and the professional service providers working with the child?', options: ['Within 24 hours', 'At the next 180-day review', 'Within five days after the plan is completed', 'Within 15 days after the plan is completed'], correct: 2, explanation: '§749.1231(d) requires the CPA to provide the service plan to the child, caregivers, and professional service providers within five days after the plan is completed. The child must also be allowed to help develop the plan (§749.1231(c)).' },
      { id: 'p3q25', domain: 'Discharge and Transfer (Subch. K)', question: 'Your service planning team decides a 10-year-old should be told in advance about a planned transfer to another placement. What must the CPA do?', options: ['Inform the child at least four days before the transfer, and give the receiving placement a transfer summary within 15 days after the transfer', 'Tell the child on the day of the transfer, and give the summary within 30 days', 'Inform the child at least 30 days before the transfer, and give the summary within five days', 'Inform the child at least 24 hours before the transfer, and give the summary within 24 hours'], correct: 0, explanation: '§749.1251(a)(3) requires telling the child at least four days before the date of discharge or transfer if the team decides advance notice is appropriate, and §749.1251(d) requires the discharge or transfer summary within 15 days. The CPA must also send prescribed medications and belongings and, unless the parent or law enforcement transports, ensure a caregiver or child placement staff accompanies the child (§749.1251(c)).' },
      { id: 'p3q26', domain: 'Child Rights (Subch. L)', question: 'A foster father suspects a 14-year-old girl in care stole money and wants to search her clothing, including having her remove some clothing. What do the rules require?', options: ['Any caregiver may search as long as another child in the home witnesses it', 'There must be reasonable suspicion of theft, and if clothing other than outer clothing is removed, only a same-sex caregiver may search, an adult same-sex witness must be present, and other children must not witness it', 'A search that involves removing clothing is never permitted under any circumstances', 'Caregivers may search at any time without suspicion if the child is under 16'], correct: 1, explanation: '§749.1305(a)(3) permits a search where a child is suspected of or was involved in a theft, based on reasonable suspicion. For a search involving removal of clothing other than outer clothing, §749.1305(b) requires a same-sex caregiver, a same-sex adult witness, and that other children do not witness the search. No body cavity search is allowed except the child\'s mouth (§749.1305(c)), and the search must be documented (§749.1307(3)).' },
      { id: 'p3q27', domain: 'Daily Care (Subch. M)', question: 'A foster parent reports that a 4-month-old fell asleep in a bouncy seat. What must the caregiver do?', options: ['Leave the infant in the seat as long as a video monitor is used', 'Fasten the safety strap and keep watching until the infant wakes', 'Cover the infant with a light blanket to prevent a chill', 'Move the infant to a crib as soon as possible'], correct: 3, explanation: '§749.1405(d) provides that an infant must not sleep in a restrictive device such as a car seat, swing, bouncy seat, or highchair, and if an infant falls asleep in one, the caregiver must move the infant to a crib as soon as possible. A covered head, face, or crib is also prohibited (§749.1405(b)), and the CPA must notify the parents of each child in each verified home of deficiencies cited under this section (§749.1405(f)).' },
      { id: 'p3q28', domain: 'Medical and Dental (Subch. N)', question: 'A 15-year-old in care asks to carry and self-administer a prescribed medication. What must the CPA do first?', options: ['Nothing, because youth age 14 and older may self-administer', 'Obtain the verbal consent of a foster parent', 'Obtain written parental consent, update the service plan with self-administration and caregiver supervision requirements, and consult the prescribing health-care professional, noting any concerns in the child\'s record', 'Obtain consent from the pharmacist who filled the prescription'], correct: 2, explanation: '§749.1501(f) allows self-administration only after the CPA obtains written parental consent, updates the service plan to include self-administration and any caregiver supervision requirements, and consults the prescribing health-care professional and notes any concerns in the child\'s record. The home must review the medication and record the daily dosage (§749.1505(e)).' },
      { id: 'p3q29', domain: 'Emergency Behavior Intervention (Subch. O)', question: 'A foster parent administers a personal restraint on a 9-year-old at 3 p.m. Monday. Which follow-up timeline applies?', options: ['Written notice to the parent within 72 hours, the caregiver discusses the incident with child placement staff within 72 hours, and child placement staff document their review within 72 hours', 'Written notice to the parent within 24 hours, and staff review within seven days', 'Written notice to the parent within seven days, with no staff discussion required', 'Written notice to the parent within 30 days, and staff review at the next quarterly visit'], correct: 0, explanation: '§749.1625(a) requires written parental notice no later than 72 hours after a personal restraint or emergency medication. Each caregiver who took part must talk with child placement staff within 72 hours (§749.1621(b)), and staff must document their review within 72 hours of the incident (§749.1623(b)).' },
      { id: 'p3q30', domain: 'Emergency Behavior Intervention (Subch. O)', question: 'A 12-year-old in a foster home has been placed in a personal restraint four times in the past seven days. What must the CPA do?', options: ['Nothing unless a fifth restraint occurs within 30 days', 'Conduct a triggered review of the placement, service plan, and EBI orders or recommendations no later than 30 days after, with the service planning team participating and the child invited', 'Conduct a review within 90 days with only the caregiver present', 'Immediately discharge the child from the home'], correct: 1, explanation: '§749.1631(a)(1)(A) requires a triggered review no later than 30 days after a personal restraint is administered on the same child four times or more within a seven-day period (or 13 times in 30 days, or more often than a written order allows). The service planning team must participate and the child must be invited (§749.1631(b)). Four triggered reviews within 90 days require examination by a mental health professional, whose recommendations the CPA must follow (§749.1631(c)).' },
    ],
  },
];
